-- Latest single-file schema for the local learning game.
-- This file is intentionally mutable. Local startup rebuilds the schema when
-- the recorded checksum no longer matches this latest file.

CREATE TABLE account (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_account_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE session_token (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    account_id BIGINT NOT NULL,
    token VARCHAR(96) NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_session_token (token),
    KEY idx_session_account (account_id),
    CONSTRAINT fk_session_account FOREIGN KEY (account_id) REFERENCES account (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE player (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    account_id BIGINT NULL,
    name VARCHAR(32) NOT NULL,
    profession VARCHAR(32) NOT NULL,
    level INT NOT NULL DEFAULT 1,
    experience INT NOT NULL DEFAULT 0,
    gold BIGINT NOT NULL DEFAULT 100,
    real_money BIGINT NOT NULL DEFAULT 0,
    guild_coin BIGINT NOT NULL DEFAULT 0,
    wealth_tier_level INT NOT NULL DEFAULT 0,
    wealth_tier VARCHAR(64) NOT NULL DEFAULT '贫民',
    strength INT NOT NULL,
    agility INT NOT NULL,
    constitution INT NOT NULL,
    intelligence INT NOT NULL,
    spirit INT NOT NULL,
    free_points INT NOT NULL DEFAULT 0,
    stamina_current INT NOT NULL DEFAULT 1000,
    stamina_updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    controller_type VARCHAR(16) NOT NULL DEFAULT 'player',
    title VARCHAR(64) NOT NULL DEFAULT '玩家',
    personality VARCHAR(64) NOT NULL DEFAULT '',
    personality_archetype VARCHAR(24) NOT NULL DEFAULT '',
    dungeon_clears INT NOT NULL DEFAULT 0,
    peak_enhancement INT NOT NULL DEFAULT 0,
    legendary_loot_count INT NOT NULL DEFAULT 0,
    current_activity_kind VARCHAR(32) NOT NULL DEFAULT 'rest',
    current_activity_text VARCHAR(240) NOT NULL DEFAULT '正在公会大厅整理装备。',
    current_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_income_at TIMESTAMP NULL,
    last_recharge_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_player_account (account_id),
    UNIQUE KEY uk_player_name (name),
    KEY idx_player_controller (controller_type, level, gold),
    CONSTRAINT fk_player_account FOREIGN KEY (account_id) REFERENCES account (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE item_template (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    item_category VARCHAR(32) NOT NULL DEFAULT 'equipment',
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    resistance_bonus INT NOT NULL DEFAULT 0,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    random_range INT NOT NULL,
    description VARCHAR(1000) NOT NULL,
    sell_price INT NOT NULL,
    stackable BOOLEAN NOT NULL DEFAULT FALSE,
    max_stack INT NOT NULL DEFAULT 1,
    effect_type VARCHAR(64) NULL,
    effect_value_json VARCHAR(1000) NULL,
    tradeable BOOLEAN NOT NULL DEFAULT TRUE,
    market_category VARCHAR(32) NOT NULL DEFAULT 'equipment',
    market_min_unit_price INT NOT NULL DEFAULT 1,
    market_max_unit_price INT NOT NULL DEFAULT 0,
    enhance_bonus_rate DECIMAL(6, 4) NOT NULL DEFAULT 0,
    min_enhance_level INT NOT NULL DEFAULT 1,
    max_enhance_level INT NOT NULL DEFAULT 15,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monster_config (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    level INT NOT NULL,
    max_hp INT NOT NULL,
    attack_power INT NOT NULL,
    armor INT NOT NULL,
    resistance INT NOT NULL,
    accuracy DECIMAL(6, 4) NOT NULL,
    evasion DECIMAL(6, 4) NOT NULL,
    crit_chance DECIMAL(6, 4) NOT NULL,
    crit_resist DECIMAL(6, 4) NOT NULL,
    speed INT NOT NULL,
    damage_type VARCHAR(16) NOT NULL,
    archetype VARCHAR(32) NOT NULL,
    mechanic VARCHAR(32) NOT NULL,
    is_boss BOOLEAN NOT NULL,
    exp_reward INT NOT NULL,
    gold_reward INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monster_loot (
    monster_id VARCHAR(64) NOT NULL,
    item_id VARCHAR(64) NOT NULL,
    drop_rate DECIMAL(10, 6) NOT NULL,
    PRIMARY KEY (monster_id, item_id),
    CONSTRAINT fk_monster_loot_monster FOREIGN KEY (monster_id) REFERENCES monster_config (id),
    CONSTRAINT fk_monster_loot_item FOREIGN KEY (item_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_config (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    difficulty VARCHAR(32) NOT NULL,
    recommended_level INT NOT NULL,
    recommended_power INT NOT NULL,
    minimum_level INT NOT NULL,
    minimum_power INT NOT NULL,
    boss_archetype VARCHAR(32) NOT NULL,
    expected_rounds INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_room (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_id VARCHAR(64) NOT NULL,
    room_config_id VARCHAR(64) NOT NULL,
    room_order INT NOT NULL,
    is_boss_room BOOLEAN NOT NULL,
    UNIQUE KEY uk_dungeon_room_config (dungeon_id, room_config_id),
    KEY idx_dungeon_room_order (dungeon_id, room_order),
    CONSTRAINT fk_dungeon_room_dungeon FOREIGN KEY (dungeon_id) REFERENCES dungeon_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_room_monster (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    room_id BIGINT NOT NULL,
    monster_id VARCHAR(64) NOT NULL,
    monster_count INT NOT NULL,
    KEY idx_room_monster_room (room_id),
    CONSTRAINT fk_room_monster_room FOREIGN KEY (room_id) REFERENCES dungeon_room (id),
    CONSTRAINT fk_room_monster_monster FOREIGN KEY (monster_id) REFERENCES monster_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_config (
    id VARCHAR(96) PRIMARY KEY,
    title VARCHAR(128) NOT NULL,
    category VARCHAR(32) NOT NULL,
    description VARCHAR(500) NOT NULL,
    lore VARCHAR(1000) NULL,
    priority INT NOT NULL,
    navigation_target VARCHAR(64) NULL,
    condition_logic VARCHAR(16) NOT NULL DEFAULT 'ALL',
    reset_period VARCHAR(16) NOT NULL DEFAULT 'lifetime',
    difficulty_score INT NOT NULL DEFAULT 1,
    reward_tier VARCHAR(32) NOT NULL DEFAULT 'normal',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_prerequisite (
    quest_id VARCHAR(96) NOT NULL,
    prerequisite_id VARCHAR(96) NOT NULL,
    PRIMARY KEY (quest_id, prerequisite_id),
    CONSTRAINT fk_quest_prereq_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_condition (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    quest_id VARCHAR(96) NOT NULL,
    condition_id VARCHAR(96) NOT NULL,
    condition_type VARCHAR(64) NOT NULL,
    target_id VARCHAR(96) NULL,
    target_value INT NOT NULL,
    condition_order INT NOT NULL,
    KEY idx_quest_condition_quest (quest_id),
    CONSTRAINT fk_quest_condition_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_reward (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    quest_id VARCHAR(96) NOT NULL,
    reward_type VARCHAR(64) NOT NULL,
    target_id VARCHAR(96) NULL,
    amount INT NOT NULL,
    reward_order INT NOT NULL,
    KEY idx_quest_reward_quest (quest_id),
    CONSTRAINT fk_quest_reward_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE chest_loot (
    chest_template_id VARCHAR(64) NOT NULL,
    reward_template_id VARCHAR(64) NOT NULL,
    min_quantity INT NOT NULL DEFAULT 1,
    max_quantity INT NOT NULL DEFAULT 1,
    weight INT NOT NULL DEFAULT 1,
    PRIMARY KEY (chest_template_id, reward_template_id),
    CONSTRAINT fk_chest_loot_chest FOREIGN KEY (chest_template_id) REFERENCES item_template (id),
    CONSTRAINT fk_chest_loot_reward FOREIGN KEY (reward_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE craft_recipe (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    result_template_id VARCHAR(64) NOT NULL,
    result_quantity INT NOT NULL DEFAULT 1,
    required_level INT NOT NULL DEFAULT 1,
    description VARCHAR(500) NOT NULL,
    CONSTRAINT fk_recipe_result FOREIGN KEY (result_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE craft_recipe_cost (
    recipe_id VARCHAR(64) NOT NULL,
    item_template_id VARCHAR(64) NOT NULL,
    quantity INT NOT NULL,
    PRIMARY KEY (recipe_id, item_template_id),
    CONSTRAINT fk_recipe_cost_recipe FOREIGN KEY (recipe_id) REFERENCES craft_recipe (id),
    CONSTRAINT fk_recipe_cost_item FOREIGN KEY (item_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE item_instance (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    template_id VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    resistance_bonus INT NOT NULL DEFAULT 0,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    sell_price INT NOT NULL,
    quantity INT NOT NULL DEFAULT 1,
    enhancement_level INT NOT NULL DEFAULT 0,
    enhancement_luck INT NOT NULL DEFAULT 0,
    refine_level INT NOT NULL DEFAULT 0,
    refine_focus VARCHAR(32) NOT NULL DEFAULT 'balanced',
    ascension_level INT NOT NULL DEFAULT 0,
    ascension_luck INT NOT NULL DEFAULT 0,
    market_lock_until TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_item_player (player_id),
    KEY idx_item_template (template_id),
    CONSTRAINT fk_item_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_slot (
    player_id BIGINT NOT NULL,
    slot_index INT NOT NULL,
    item_id BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, slot_index),
    UNIQUE KEY uk_inventory_item (item_id),
    CONSTRAINT fk_inventory_player FOREIGN KEY (player_id) REFERENCES player (id),
    CONSTRAINT fk_inventory_item FOREIGN KEY (item_id) REFERENCES item_instance (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_slot (
    player_id BIGINT NOT NULL,
    slot_name VARCHAR(32) NOT NULL,
    item_id BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, slot_name),
    UNIQUE KEY uk_equipment_item (item_id),
    CONSTRAINT fk_equipment_player FOREIGN KEY (player_id) REFERENCES player (id),
    CONSTRAINT fk_equipment_item FOREIGN KEY (item_id) REFERENCES item_instance (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gem_template (
    template_id VARCHAR(64) PRIMARY KEY,
    gem_kind VARCHAR(32) NOT NULL,
    rank_level INT NOT NULL,
    stat_key VARCHAR(32) NOT NULL,
    stat_value DECIMAL(12, 4) NOT NULL,
    slot_kind VARCHAR(32) NOT NULL DEFAULT 'any',
    next_template_id VARCHAR(64) NULL,
    sort_order INT NOT NULL DEFAULT 0,
    CONSTRAINT fk_gem_template_item FOREIGN KEY (template_id) REFERENCES item_template (id),
    CONSTRAINT fk_gem_template_next FOREIGN KEY (next_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_socket (
    item_id BIGINT NOT NULL,
    socket_index INT NOT NULL,
    unlocked BOOLEAN NOT NULL DEFAULT TRUE,
    gem_item_id BIGINT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (item_id, socket_index),
    UNIQUE KEY uk_socket_gem_item (gem_item_id),
    CONSTRAINT fk_socket_item FOREIGN KEY (item_id) REFERENCES item_instance (id) ON DELETE CASCADE,
    CONSTRAINT fk_socket_gem FOREIGN KEY (gem_item_id) REFERENCES item_instance (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_affix (
    item_id BIGINT NOT NULL,
    affix_index INT NOT NULL,
    stat_key VARCHAR(32) NOT NULL,
    stat_value DECIMAL(12, 4) NOT NULL,
    tier INT NOT NULL,
    locked BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (item_id, affix_index),
    CONSTRAINT fk_affix_item FOREIGN KEY (item_id) REFERENCES item_instance (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_processing_log (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    item_id BIGINT NOT NULL,
    action_type VARCHAR(32) NOT NULL,
    success BOOLEAN NOT NULL,
    summary VARCHAR(512) NOT NULL,
    power_before INT NOT NULL DEFAULT 0,
    power_after INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_processing_player (player_id, created_at),
    KEY idx_processing_item (item_id, created_at),
    CONSTRAINT fk_processing_player FOREIGN KEY (player_id) REFERENCES player (id),
    CONSTRAINT fk_processing_item FOREIGN KEY (item_id) REFERENCES item_instance (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    dungeon_id VARCHAR(64) NOT NULL,
    config_version VARCHAR(64) NOT NULL,
    request_id VARCHAR(96) NULL,
    success BOOLEAN NOT NULL,
    rating VARCHAR(8) NOT NULL,
    monsters_killed INT NOT NULL,
    exp_gained INT NOT NULL,
    gold_gained BIGINT NOT NULL,
    combat_power INT NOT NULL DEFAULT 0,
    recommended_power INT NOT NULL DEFAULT 0,
    player_max_hp INT NOT NULL DEFAULT 0,
    player_final_hp INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_dungeon_run_request (player_id, request_id),
    KEY idx_dungeon_run_player (player_id),
    CONSTRAINT fk_dungeon_run_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_loot (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    loot_order INT NOT NULL,
    item_id BIGINT NULL,
    item_template_id VARCHAR(64) NOT NULL,
    item_name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    resistance_bonus INT NOT NULL DEFAULT 0,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    sell_price INT NOT NULL,
    enhancement_level INT NOT NULL DEFAULT 0,
    enhancement_luck INT NOT NULL DEFAULT 0,
    KEY idx_run_loot_run (dungeon_run_id),
    KEY idx_run_loot_template (item_template_id),
    CONSTRAINT fk_run_loot_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE,
    CONSTRAINT fk_run_loot_template FOREIGN KEY (item_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_log (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    log_order INT NOT NULL,
    text VARCHAR(1000) NOT NULL,
    KEY idx_run_log_run (dungeon_run_id, log_order),
    CONSTRAINT fk_run_log_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_frame (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    frame_index INT NOT NULL,
    text VARCHAR(1000) NOT NULL,
    tone VARCHAR(32) NOT NULL,
    room_label VARCHAR(64) NULL,
    enemy_name VARCHAR(128) NULL,
    player_hp INT NOT NULL DEFAULT 0,
    player_max_hp INT NOT NULL DEFAULT 0,
    enemy_hp INT NOT NULL DEFAULT 0,
    enemy_max_hp INT NOT NULL DEFAULT 0,
    actor VARCHAR(16) NOT NULL DEFAULT 'system',
    event_type VARCHAR(16) NOT NULL DEFAULT 'phase',
    damage INT NOT NULL DEFAULT 0,
    critical BOOLEAN NOT NULL DEFAULT FALSE,
    missed BOOLEAN NOT NULL DEFAULT FALSE,
    skill_id VARCHAR(96) NULL,
    skill_name VARCHAR(128) NULL,
    visual_key VARCHAR(64) NULL,
    target_side VARCHAR(16) NULL,
    effect_value INT NOT NULL DEFAULT 0,
    KEY idx_run_frame_run (dungeon_run_id, frame_index),
    CONSTRAINT fk_run_frame_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE skill_template (
    id VARCHAR(96) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    owner_scope VARCHAR(16) NOT NULL,
    profession VARCHAR(32) NOT NULL DEFAULT 'any',
    archetype VARCHAR(32) NOT NULL DEFAULT 'any',
    unlock_level INT NOT NULL DEFAULT 1,
    max_rank INT NOT NULL DEFAULT 1,
    category VARCHAR(32) NOT NULL,
    target_type VARCHAR(32) NOT NULL DEFAULT 'enemy',
    damage_type VARCHAR(32) NOT NULL DEFAULT '',
    base_multiplier DECIMAL(8, 4) NOT NULL DEFAULT 0,
    rank_multiplier_growth DECIMAL(8, 4) NOT NULL DEFAULT 0,
    cooldown INT NOT NULL DEFAULT 0,
    mp_cost_base INT NOT NULL DEFAULT 0,
    mp_cost_growth INT NOT NULL DEFAULT 0,
    effect_type VARCHAR(32) NOT NULL DEFAULT 'damage',
    effect_power_base DECIMAL(8, 4) NOT NULL DEFAULT 0,
    effect_power_growth DECIMAL(8, 4) NOT NULL DEFAULT 0,
    duration_rounds INT NOT NULL DEFAULT 0,
    trigger_kind VARCHAR(32) NOT NULL DEFAULT 'default',
    priority INT NOT NULL DEFAULT 0,
    visual_key VARCHAR(64) NOT NULL DEFAULT 'basic-slash',
    description VARCHAR(500) NOT NULL,
    tier_coef DECIMAL(8, 4) NOT NULL DEFAULT 1,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_skill_owner_profession (owner_scope, profession, unlock_level),
    KEY idx_skill_owner_archetype (owner_scope, archetype, unlock_level)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE player_skill (
    player_id BIGINT NOT NULL,
    skill_id VARCHAR(96) NOT NULL,
    skill_rank INT NOT NULL DEFAULT 1,
    learned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, skill_id),
    KEY idx_player_skill_skill (skill_id),
    CONSTRAINT fk_player_skill_player FOREIGN KEY (player_id) REFERENCES player (id) ON DELETE CASCADE,
    CONSTRAINT fk_player_skill_template FOREIGN KEY (skill_id) REFERENCES skill_template (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE economy_audit_event (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    event_type VARCHAR(64) NOT NULL,
    reference_id VARCHAR(96) NULL,
    dungeon_id VARCHAR(64) NULL,
    success BOOLEAN NULL,
    rating VARCHAR(8) NULL,
    monsters_killed INT NOT NULL DEFAULT 0,
    exp_gained INT NOT NULL DEFAULT 0,
    gold_gained BIGINT NOT NULL DEFAULT 0,
    loot_count INT NOT NULL DEFAULT 0,
    sweep_times INT NOT NULL DEFAULT 0,
    combat_power INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_economy_player (player_id),
    KEY idx_economy_dungeon (dungeon_id),
    CONSTRAINT fk_economy_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE config_bundle (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    version VARCHAR(64) NOT NULL,
    checksum VARCHAR(64) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_config_version (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_progress (
    player_id BIGINT NOT NULL,
    quest_id VARCHAR(96) NOT NULL,
    status VARCHAR(24) NOT NULL,
    current_value INT NOT NULL DEFAULT 0,
    period_key VARCHAR(24) NOT NULL DEFAULT 'lifetime',
    cycle_key VARCHAR(16) NULL,
    claimed_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, quest_id),
    CONSTRAINT fk_quest_progress_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_condition_progress (
    player_id BIGINT NOT NULL,
    quest_id VARCHAR(96) NOT NULL,
    condition_id VARCHAR(96) NOT NULL,
    current_value INT NOT NULL DEFAULT 0,
    completed BOOLEAN NOT NULL DEFAULT FALSE,
    period_key VARCHAR(24) NOT NULL DEFAULT 'lifetime',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, quest_id, condition_id),
    KEY idx_condition_progress_player (player_id, quest_id),
    CONSTRAINT fk_condition_progress_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE market_listing (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    seller_player_id BIGINT NULL,
    seller_name VARCHAR(64) NOT NULL,
    item_id BIGINT NULL,
    item_template_id VARCHAR(64) NOT NULL,
    quantity INT NOT NULL DEFAULT 1,
    unit_price BIGINT NOT NULL DEFAULT 0,
    item_category VARCHAR(32) NOT NULL DEFAULT 'equipment',
    stackable BOOLEAN NOT NULL DEFAULT FALSE,
    item_enhancement_level INT NOT NULL DEFAULT 0,
    item_enhancement_luck INT NOT NULL DEFAULT 0,
    item_refine_level INT NOT NULL DEFAULT 0,
    item_ascension_level INT NOT NULL DEFAULT 0,
    snapshot_name VARCHAR(128) NULL,
    snapshot_item_type VARCHAR(32) NULL,
    snapshot_item_category VARCHAR(32) NOT NULL DEFAULT 'equipment',
    snapshot_quality VARCHAR(32) NULL,
    snapshot_required_level INT NOT NULL DEFAULT 1,
    snapshot_attack_bonus INT NOT NULL DEFAULT 0,
    snapshot_defense_bonus INT NOT NULL DEFAULT 0,
    snapshot_resistance_bonus INT NOT NULL DEFAULT 0,
    snapshot_hp_bonus INT NOT NULL DEFAULT 0,
    snapshot_mp_bonus INT NOT NULL DEFAULT 0,
    snapshot_crit_bonus DECIMAL(10, 6) NOT NULL DEFAULT 0,
    snapshot_sell_price INT NOT NULL DEFAULT 1,
    snapshot_description VARCHAR(1000) NULL,
    snapshot_effect_type VARCHAR(64) NULL,
    snapshot_effect_value VARCHAR(1000) NULL,
    snapshot_processing_summary VARCHAR(1000) NULL,
    price BIGINT NOT NULL,
    status VARCHAR(24) NOT NULL,
    buyer_player_id BIGINT NULL,
    sold_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_market_status (status, created_at),
    KEY idx_market_seller (seller_player_id),
    KEY idx_market_item_template (item_template_id),
    CONSTRAINT fk_market_seller FOREIGN KEY (seller_player_id) REFERENCES player (id),
    CONSTRAINT fk_market_buyer FOREIGN KEY (buyer_player_id) REFERENCES player (id),
    CONSTRAINT fk_market_item FOREIGN KEY (item_id) REFERENCES item_instance (id) ON DELETE SET NULL,
    CONSTRAINT fk_market_listing_template FOREIGN KEY (item_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE chat_message (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NULL,
    sender_name VARCHAR(64) NOT NULL,
    kind VARCHAR(32) NOT NULL,
    text VARCHAR(500) NOT NULL,
    channel VARCHAR(24) NOT NULL DEFAULT 'world',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_chat_created (created_at),
    KEY idx_chat_channel (channel, id),
    CONSTRAINT fk_chat_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Guild social ecosystem (P1): guild + membership.
CREATE TABLE guild (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(64) NOT NULL UNIQUE,
    leader_robot_id BIGINT NULL,
    level INT NOT NULL DEFAULT 1,
    fund BIGINT NOT NULL DEFAULT 0,
    total_contribution BIGINT NOT NULL DEFAULT 0,
    weekly_contribution BIGINT NOT NULL DEFAULT 0,
    recruiting_blurb VARCHAR(200) NOT NULL DEFAULT '',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_guild_leader FOREIGN KEY (leader_robot_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE guild_member (
    guild_id BIGINT NOT NULL,
    player_id BIGINT NOT NULL PRIMARY KEY,
    role VARCHAR(16) NOT NULL DEFAULT 'member',
    weekly_contribution BIGINT NOT NULL DEFAULT 0,
    total_contribution BIGINT NOT NULL DEFAULT 0,
    joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_guild_member_guild (guild_id),
    CONSTRAINT fk_guild_member_guild FOREIGN KEY (guild_id) REFERENCES guild (id),
    CONSTRAINT fk_guild_member_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Guild social ecosystem (P2): weekly shared-HP-pool boss + per-member contribution.
CREATE TABLE guild_boss (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    guild_id BIGINT NOT NULL,
    week_key VARCHAR(12) NOT NULL,
    tier INT NOT NULL DEFAULT 1,
    name VARCHAR(64) NOT NULL,
    hp_max BIGINT NOT NULL,
    hp_current BIGINT NOT NULL,
    status VARCHAR(12) NOT NULL DEFAULT 'alive',
    spawned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    killed_at TIMESTAMP NULL,
    UNIQUE KEY uk_guild_boss (guild_id, week_key, tier),
    KEY idx_guild_boss_status (guild_id, status),
    CONSTRAINT fk_guild_boss_guild FOREIGN KEY (guild_id) REFERENCES guild (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE guild_boss_contribution (
    guild_id BIGINT NOT NULL,
    week_key VARCHAR(12) NOT NULL,
    player_id BIGINT NOT NULL,
    damage BIGINT NOT NULL DEFAULT 0,
    attempts INT NOT NULL DEFAULT 0,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (guild_id, week_key, player_id),
    KEY idx_gbc_rank (guild_id, week_key, damage),
    CONSTRAINT fk_gbc_guild FOREIGN KEY (guild_id) REFERENCES guild (id),
    CONSTRAINT fk_gbc_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Guild social ecosystem (P3): guild coin shop.
CREATE TABLE guild_shop_offer (
    id VARCHAR(48) PRIMARY KEY,
    name VARCHAR(64) NOT NULL,
    description VARCHAR(160) NOT NULL DEFAULT '',
    cost_guild_coin INT NOT NULL,
    reward_kind VARCHAR(24) NOT NULL,
    reward_ref VARCHAR(64) NULL,
    reward_amount INT NOT NULL DEFAULT 0,
    sort_order INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO guild_shop_offer (id, name, description, cost_guild_coin, reward_kind, reward_ref, reward_amount, sort_order) VALUES
    ('guild_gold_small', '公会金币补给', '用公会币兑换 50,000 金币', 50, 'gold', NULL, 50000, 1),
    ('guild_gold_large', '公会金库大额', '用公会币兑换 250,000 金币', 200, 'gold', NULL, 250000, 2),
