    CONSTRAINT fk_arena_purchase_offer FOREIGN KEY (offer_id) REFERENCES arena_shop_offer (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seed robots with a believable spread of level / wealth / archetype instead of 200
-- identical level-1 paupers, so the leaderboard and "alive world" read as real from the
-- first tick. User accounts are intentionally not seeded.
INSERT IGNORE INTO player
    (account_id, name, profession, level, experience, gold,
     wealth_tier_level, wealth_tier, strength, agility, constitution,
     intelligence, spirit, free_points, controller_type, title, personality,
     personality_archetype, dungeon_clears, peak_enhancement, legendary_loot_count)
WITH RECURSIVE seq(n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM seq WHERE n < 400
),
robots AS (
    SELECT
        n,
        CASE MOD(n, 3)
            WHEN 0 THEN 'warrior'
            WHEN 1 THEN 'ranger'
            ELSE 'mage'
        END AS profession,
        -- Pyramid level distribution: a newbie base up to a thin, strong veteran cohort,
        -- giving the player a real ladder to chase. Robots also keep climbing over real
        -- time via RobotProgressionService passive growth.
        CASE
            WHEN n <= 150 THEN 3 + MOD(n, 13)    -- 3..15   (150 newbie base)
            WHEN n <= 270 THEN 14 + MOD(n, 19)   -- 14..32  (120 mid)
            WHEN n <= 350 THEN 30 + MOD(n, 21)   -- 30..50  (80 upper-mid)
            WHEN n <= 388 THEN 46 + MOD(n, 19)   -- 46..64  (38 veterans)
            ELSE 64 + MOD(n, 19)                 -- 64..82  (12 strong top cohort)
        END AS lvl
    FROM seq
)
SELECT
    NULL,
    CONCAT(
        CASE MOD(n - 1, 24)
            WHEN 0 THEN 'Aelric'
            WHEN 1 THEN 'Brennor'
            WHEN 2 THEN 'Cedric'
            WHEN 3 THEN 'Dorian'
            WHEN 4 THEN 'Eldric'
            WHEN 5 THEN 'Faelar'
            WHEN 6 THEN 'Garrick'
            WHEN 7 THEN 'Hadrian'
            WHEN 8 THEN 'Isolde'
            WHEN 9 THEN 'Jareth'
            WHEN 10 THEN 'Kaelen'
            WHEN 11 THEN 'Lorian'
            WHEN 12 THEN 'Maelis'
            WHEN 13 THEN 'Nerys'
            WHEN 14 THEN 'Orin'
            WHEN 15 THEN 'Perrin'
            WHEN 16 THEN 'Quillan'
            WHEN 17 THEN 'Rowan'
            WHEN 18 THEN 'Seraphine'
            WHEN 19 THEN 'Thalia'
            WHEN 20 THEN 'Ulric'
            WHEN 21 THEN 'Vaelin'
            WHEN 22 THEN 'Wynna'
            ELSE 'Yseult'
        END,
        ' ',
        -- 24 given names x 17 surnames = 408 unique combos, enough for 400 robots
        -- without tripping the uk_player_name unique constraint (INSERT IGNORE would
        -- silently drop collisions).
        CASE FLOOR((n - 1) / 24)
            WHEN 0 THEN 'Stormvale'
            WHEN 1 THEN 'Ashenford'
            WHEN 2 THEN 'Moonbrook'
            WHEN 3 THEN 'Ironhollow'
            WHEN 4 THEN 'Dawnmere'
            WHEN 5 THEN 'Ravenscar'
            WHEN 6 THEN 'Thornwick'
            WHEN 7 THEN 'Starfall'
            WHEN 8 THEN 'Silverkeep'
            WHEN 9 THEN 'Frostmere'
            WHEN 10 THEN 'Emberfall'
            WHEN 11 THEN 'Duskwater'
            WHEN 12 THEN 'Greycliff'
            WHEN 13 THEN 'Wyrmrest'
            WHEN 14 THEN 'Brightwood'
            WHEN 15 THEN 'Hollowmere'
            ELSE 'Stoneford'
        END
    ),
    profession,
    lvl,
    0,
    -- Gold scales with level (veterans are richer), plus a small per-bot jitter.
    80 + lvl * 320 + MOD(n, 9) * 60,
    -- Wealth tier tracks level, capped at 7.
    LEAST(7, FLOOR(lvl / 8)),
    CASE LEAST(7, FLOOR(lvl / 8))
        WHEN 0 THEN '贫民'
        WHEN 1 THEN '平民'
        WHEN 2 THEN '小康'
        WHEN 3 THEN '富农'
        WHEN 4 THEN '富商'
        WHEN 5 THEN '豪绅'
        WHEN 6 THEN '巨贾'
        ELSE '富甲一方'
    END,
    -- Base attributes follow the profession template, grow with level, and carry a
    -- small per-bot jitter so same-profession bots aren't carbon copies.
    (CASE profession WHEN 'mage' THEN 3 WHEN 'ranger' THEN 6 ELSE 10 END) + FLOOR(lvl / 2) + MOD(n, 3),
    (CASE profession WHEN 'ranger' THEN 10 ELSE 5 END) + FLOOR(lvl / 2) + MOD(n + 1, 3),
    (CASE profession WHEN 'warrior' THEN 8 ELSE 5 END) + FLOOR(lvl / 2) + MOD(n + 2, 3),
    (CASE profession WHEN 'mage' THEN 10 ELSE 4 END) + FLOOR(lvl / 2) + MOD(n, 2),
    (CASE profession WHEN 'mage' THEN 9 ELSE 4 END) + FLOOR(lvl / 2) + MOD(n + 1, 2),
    0,
    'robot',
    CASE MOD(n, 10)
        WHEN 0 THEN '新晋冒险者'
        WHEN 1 THEN '副本练习生'
        WHEN 2 THEN '商会新人'
        WHEN 3 THEN '强化学徒'
        WHEN 4 THEN '低价观察员'
        WHEN 5 THEN '巡林新人'
        WHEN 6 THEN '新月旅人'
        WHEN 7 THEN '野队队员'
        WHEN 8 THEN '掉落记录员'
        ELSE '公会新人'
    END,
    CASE MOD(n, 9)
        WHEN 0 THEN '从第一层副本开始练级。'
        WHEN 1 THEN '关注装备评分和副本门槛。'
        WHEN 2 THEN '会在市场寻找低价升级装备。'
        WHEN 3 THEN '金币够了会尝试强化。'
        WHEN 4 THEN '不会越级硬闯副本。'
        WHEN 5 THEN '优先补齐空装备位。'
        WHEN 6 THEN '喜欢比较装备词条。'
        WHEN 7 THEN '会按日常任务推进。'
        ELSE '偶尔在世界频道聊天。'
    END,
    -- Structured archetype: mostly casual/newbie, with merchant/social/showoff sprinkled
    -- in and veterans skewing hardcore. Drives scoring weights + selection temperature.
    CASE
        WHEN MOD(n, 17) = 3 THEN 'MERCHANT'
        WHEN MOD(n, 17) = 7 THEN 'SOCIAL'
        WHEN MOD(n, 13) = 5 THEN 'SHOWOFF'
        WHEN lvl >= 28 THEN 'HARDCORE'
        WHEN lvl <= 6 THEN 'NEWBIE'
        ELSE 'CASUAL'
    END,
    -- Lifetime stats scale with level so profiles and the leaderboard look lived-in.
    lvl * 3 + MOD(n, 5),
    LEAST(15, FLOOR(lvl / 4)),
    FLOOR(lvl / 10)
FROM robots;

